from litestar import patch, Request
from litestar.dto import DataclassDTO
from litestar.exceptions import NotFoundException, NotAuthorizedException

@patch(path="/procurement/contracts/{contract_id:int}", dto=ContractPatchDTO)
async def update_contract_terms(
    contract_id: int,
    data: ContractUpdateData,
    request: Request,
    contract_repo: ContractRepository
) -> Contract:
    contract = await contract_repo.get(contract_id)
    if not contract:
        raise NotFoundException(detail="Contract not found")
    if contract.buyer_org_id != request.user.org_id and contract.vendor_org_id != request.user.org_id:
        raise NotAuthorizedException(detail="Forbidden: organization is not a counterparty to this contract")
    return await contract_repo.update(contract, data)
